      "most_likely_effort": 20
    },
    {
      "activity_id": "ACT-3",
      "activity_name": "Subpackage Extraction (orderer & membership)",
      "activity_description": "Extract orderer types (BatchSize, Kafka, EtcdRaft, ConsensusState) into pkg/configtx/orderer and membership types (SigningIdentityInfo, OUIdentifier, CryptoConfig, NodeOUs) into pkg/configtx/membership.",
